package com.thang.nihongo_user.service;
import com.thang.nihongo_user.model.*;import com.thang.nihongo_user.repository.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.autoconfigure.domain.EntityScan;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.context.annotation.*;import org.springframework.data.jpa.repository.config.EnableJpaRepositories;import org.springframework.test.context.ContextConfiguration;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.transaction.annotation.*;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import java.time.*;import java.math.BigDecimal;import java.util.concurrent.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@DataJpaTest(properties={"spring.config.import=","spring.datasource.url=jdbc:h2:mem:additional_learning;MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=create-drop","spring.jpa.properties.hibernate.dialect=org.hibernate.dialect.H2Dialect","spring.jpa.show-sql=false"})
@AutoConfigureTestDatabase(replace=AutoConfigureTestDatabase.Replace.NONE) @ContextConfiguration(classes=AdditionalLearningPersistenceTest.Config.class) @Transactional(propagation=Propagation.NOT_SUPPORTED)
class AdditionalLearningPersistenceTest {
 @TestConfiguration @EntityScan(basePackageClasses=Course.class) @EnableJpaRepositories(basePackageClasses=ICourseRepository.class)
 @Import({ClassroomService.class,CourseRefundService.class,CoursePurchaseService.class,PromotionService.class,StudyActivityService.class,LearningFeaturesService.class}) static class Config {@Bean ObjectMapper mapper(){return new ObjectMapper();}}
 @Autowired ClassroomService school;@Autowired CourseRefundService refunds;@Autowired CoursePurchaseService purchase;@Autowired LearningFeaturesService learning;@Autowired ClassroomRepository classes;@Autowired ClassroomMemberRepository members;@Autowired ClassroomAssignmentRepository assignments;@Autowired ExamAttemptRepository attempts;@Autowired ExamFeedbackRepository feedback;@Autowired ICourseRepository courses;@Autowired ICoursePackageRepository packages;@Autowired IUserSubscriptionRepository subscriptions;@Autowired IUserWalletRepository wallets;@Autowired IWalletTransactionRepository ledger;@Autowired CoursePurchaseRepository purchases;@Autowired CourseRefundRepository refundRows;@Autowired AdminCommerceAuditRepository audits;@Autowired LessonCompletionRepository completions;@Autowired StudyActivityRepository activity;@Autowired PlatformTransactionManager transactionManager;
 @MockitoBean ClassroomContentClient content;@MockitoBean ClassroomUserClient directory;
 String student;Long courseId,packageId;
 @BeforeEach void setup(){feedback.deleteAll();attempts.deleteAll();assignments.deleteAll();members.deleteAll();classes.deleteAll();refundRows.deleteAll();purchases.deleteAll();subscriptions.deleteAll();ledger.deleteAll();wallets.deleteAll();packages.deleteAll();courses.deleteAll();audits.deleteAll();completions.deleteAll();activity.deleteAll();student=UUID.randomUUID().toString();var c=courses.saveAndFlush(Course.builder().courseName("N3").levelId(3L).active(CourseStatus.ACTIVE).build());courseId=c.getCourseId();packageId=packages.saveAndFlush(CoursePackage.builder().course(c).packageName("Month").durationDays(30).price(new BigDecimal("10000")).isActive(true).build()).getPackageId();var wallet=new UserWallet();wallet.setUserId(student);wallet.setBalance(new BigDecimal("50000"));wallets.saveAndFlush(wallet);when(content.exam(1L)).thenReturn(new ClassroomContentClient.Exam(1L,"Quiz","teacher",List.of(question(10L,"C"),question(20L,"D"))));when(directory.learners(List.of(student))).thenReturn(List.of(new ClassroomUserClient.Learner(student,"Learner","learner@example.test")));}
 ClassroomContentClient.Question question(Long id,String correct){return new ClassroomContentClient.Question(id,2L,"Lesson",1L,"Book",3L,"N3",1L,"Choice","NORMAL","日本語","A","B","C","D",correct);}
 void subscribe(){var s=new UserSubscription();s.setUserId(student);s.setCourseId(courseId);s.setPackageId(packageId);s.setStatus(SubscriptionStatus.ACTIVE);s.setExpiredAt(LocalDateTime.now().plusDays(30));subscriptions.saveAndFlush(s);}
 ClassroomService.AssignmentView assignment(){subscribe();var c=school.create("teacher",new ClassroomService.ClassInput("Class","",courseId));school.addMembers("teacher",false,c.getId(),List.of(student));var a=school.assign("teacher",false,c.getId(),new ClassroomService.AssignmentInput("Exam",1L,"EXAM",30,LocalDateTime.now().minusMinutes(1),LocalDateTime.now().plusHours(1)));return school.publish("teacher",false,a.id(),a.version());}
 @Test void teacherAndLearnerScopesAreEnforcedAndAnswerKeysRemainHidden(){var a=assignment();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->school.members("another",false,a.classroomId(),0));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->school.start("outsider",a.id()));var e=school.start(student,a.id());assertTrue(e.questions().stream().allMatch(q->q.correctAnswer()==null));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->school.read("outsider",e.id()));assertEquals(e.id(),school.start(student,a.id()).id());assertEquals(1,attempts.count());}
 @Test void serverGradesThePublishedSnapshotAndSubmissionIsIdempotent(){var a=assignment();var e=school.start(student,a.id());when(content.exam(1L)).thenReturn(new ClassroomContentClient.Exam(1L,"Changed","teacher",List.of(question(10L,"A"),question(20L,"A"))));var result=school.save(student,e.id(),new ClassroomService.Answers(Map.of(10L,"A",20L,"D"),e.version()),true);assertTrue(result.finished());assertEquals(50,result.score());assertFalse(result.answersVisible());assertEquals(50,school.save(student,e.id(),new ClassroomService.Answers(Map.of(10L,"C",20L,"D"),0),true).score());var preview=school.inspect("teacher",false,e.id());assertEquals("C",preview.questions().get(0).correctAnswer());school.comment("teacher",false,e.id(),new ClassroomService.FeedbackInput(10L,"Review this answer"));assertEquals(1,school.feedback(student,false,false,e.id(),0).getTotalElements());}
 @Test void deadlineUsesSavedAnswersAndRejectsLateAnswerChanges(){var a=assignment();var e=school.start(student,a.id());var saved=school.save(student,e.id(),new ClassroomService.Answers(Map.of(10L,"A"),e.version()),false);new TransactionTemplate(transactionManager).executeWithoutResult(tx->{var row=attempts.findById(e.id()).orElseThrow();row.setEndsAt(LocalDateTime.now().minusSeconds(1));attempts.saveAndFlush(row);});var result=school.save(student,e.id(),new ClassroomService.Answers(Map.of(10L,"C",20L,"D"),saved.version()),true);assertTrue(result.finished());assertEquals(0,result.score());assertEquals("A",result.questions().get(0).chosen());}
 @Test void staleAutosaveAndQuestionsOutsideSnapshotAreRejected(){var a=assignment();var e=school.start(student,a.id());var saved=school.save(student,e.id(),new ClassroomService.Answers(Map.of(10L,"C"),e.version()),false);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->school.save(student,e.id(),new ClassroomService.Answers(Map.of(20L,"D"),e.version()),false));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->school.save(student,e.id(),new ClassroomService.Answers(Map.of(999L,"D"),saved.version()),false));}
 @Test void concurrentStartsHaveOnlyOneAttempt()throws Exception{var a=assignment();var pool=Executors.newFixedThreadPool(2);try{var first=pool.submit(()->school.start(student,a.id()).id());var second=pool.submit(()->school.start(student,a.id()).id());assertEquals(first.get(15,TimeUnit.SECONDS),second.get(15,TimeUnit.SECONDS));assertEquals(1,attempts.count());}finally{pool.shutdownNow();}}
 @Test void refundCreditsActualPriceOnceAndCanRevokeAccess(){purchase.purchase(student,courseId,packageId,UUID.randomUUID().toString(),false);var original=purchases.findAll().get(0);var request=refunds.request("admin",new CourseRefundService.Request(original.getId(),"Refund requested by support",true));var result=refunds.review("reviewer",request.getId(),new CourseRefundService.Review(true,"Approved after checking purchase",request.getVersion()));assertEquals("APPROVED",result.getStatus());assertEquals(0,new BigDecimal("50000").compareTo(wallets.findByUserId(student).orElseThrow().getBalance()));assertFalse(subscriptions.existsActive(student,courseId));refunds.review("reviewer",request.getId(),new CourseRefundService.Review(true,"Retry after lost response",0));assertEquals(2,ledger.count());assertEquals(1,refundRows.count());}
 @Test void refundRollbackKeepsBalanceAndPendingStateOnLedgerFailure(){purchase.purchase(student,courseId,packageId,UUID.randomUUID().toString(),false);var original=purchases.findAll().get(0);var request=refunds.request("admin",new CourseRefundService.Request(original.getId(),"Refund requested by support",false));new TransactionTemplate(transactionManager).executeWithoutResult(tx->{refunds.review("admin",request.getId(),new CourseRefundService.Review(true,"Approved but database rolls back",request.getVersion()));tx.setRollbackOnly();});assertEquals("PENDING",refundRows.findById(request.getId()).orElseThrow().getStatus());assertEquals(0,new BigDecimal("40000").compareTo(wallets.findByUserId(student).orElseThrow().getBalance()));assertEquals(1,ledger.count());}
 @Test void completionRequiresContentAccessAndIsIdempotent(){when(content.lesson(2L)).thenReturn(new ClassroomContentClient.Lesson(2L,"Lesson"));learning.complete(student,2L,true);learning.complete(student,2L,true);assertEquals(1,completions.count());assertEquals(1,activity.count());learning.complete(student,2L,false);assertEquals(0,completions.count());when(content.lesson(3L)).thenThrow(new IllegalStateException("access denied"));assertThrows(IllegalStateException.class,()->learning.complete(student,3L,true));assertEquals(0,completions.count());}
}
